/** @file pps.h
 * @brief Pulse per second on PA0, generated by hardware output compare.
 *
 * TIM5 free runs at 1 MHz and its channel 1 output drives PA0 directly, so the
 * edge the scope sees is produced by the timer comparator with no instruction
 * executed at that instant. Part 7 forbids polling the global clock to find the
 * edge, and an interrupt that sets a GPIO would be only marginally better: with
 * two CAN receive workers running preemptive at priority 0, interrupt latency
 * is a few microseconds and is not bounded. The measurement this lab is graded
 * on is edge spread, so nothing software-timed belongs in that path.
 *
 * The same counter is the timestamp source for the whole sync path. F_k has to
 * be expressed in the units the compare register takes, or every arming adds a
 * conversion and its error. One microsecond of resolution is far below the
 * receive jitter measured in P6, so nothing is lost (TASKS.md D21).
 */
#ifndef PPS_H_
#define PPS_H_
#include <stdbool.h>
#include <stdint.h>
/** @brief Ticks per second of the PPS time base. */
#define PPS_TICK_HZ 1000000U
/** @brief Start the counter and claim PA0 as the compare output.
 * @return Zero, or a negative error.
 */
int pps_init(void);
/** @brief Read the free running counter.
 *
 * Safe from any context, including an interrupt, and is a single register read.
 * @return Counter value in microseconds, wrapping at 32 bits.
 */
uint32_t pps_now(void);
/** @brief Report whether the counter is running.
 * @return True once pps_init() has succeeded.
 */
bool pps_ready(void);
/** @brief Schedule the next edge and keep scheduling after it.
 *
 * Called once a global timeline exists. Each edge rearms the next from the
 * current estimate, so the schedule follows the master rather than free
 * running from the first edge.
 */
void pps_start(void);
/** @brief Count edges emitted since boot.
 * @return Edge count.
 */
uint32_t pps_edges(void);
/** @brief What one edge looked like, for the console line Part 6 requires. */
struct pps_report {
	uint64_t global_us;
	uint32_t local_ticks;
	int32_t ratio;
	int32_t correction_us;
	uint32_t edge;
};
/** @brief Collect the most recent edge, once.
 *
 * The timer interrupt records an edge and returns; it must never print, since
 * a console line at 115200 baud takes milliseconds and would hold off the CAN
 * receive workers every second. A thread calls this and does the printing.
 * @param out Destination, written only when true is returned.
 * @return True when an edge has happened since the last call.
 */
bool pps_take_report(struct pps_report *out);
#endif
